import { forwardRef, useId, useState } from 'react';
import type { ButtonHTMLAttributes, HTMLAttributes, KeyboardEvent, ReactNode } from 'react';
import { cx } from '@/lib/cx';
import { useStrings } from '@/lib/i18n';
import { Button } from './button';
import type { ButtonVariant } from './button';
import { usePopoverAnchor } from './popover';
import './menu.css';

/**
 * B20 · Menu — a dropdown of ACTIONS (never navigation, never selection —
 * selection is a Select or Combobox). Built on the native popover
 * attribute: top layer, light dismiss, and Esc come from the browser.
 * Items are verbs that name their object, exactly like buttons.
 */
export interface MenuItemSpec {
  label: string;
  onSelect: () => void;
  /** 16px stroke icon before the label. */
  icon?: ReactNode;
  /** Mono metadata after the label, e.g. a shortcut. */
  meta?: string;
  /** Destructive tone: --sv-bad text. Confirm destructive work in a Dialog. */
  danger?: boolean;
  disabled?: boolean;
}

export type MenuItem = MenuItemSpec | 'separator';

interface MenuPanelProps {
  id: string;
  items: MenuItem[];
  labelledBy: string;
  onClose: () => void;
  panelRef: React.RefObject<HTMLDivElement | null>;
  align: 'start' | 'end';
}

function MenuPanel({ id, items, labelledBy, onClose, panelRef, align }: MenuPanelProps) {
  const tr = useStrings();
  const actionable = items.filter((i): i is MenuItemSpec => i !== 'separator' && !i.disabled);

  function focusItem(delta: number) {
    const nodes = panelRef.current?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]:enabled');
    if (!nodes || nodes.length === 0) return;
    const list = Array.from(nodes);
    const current = list.indexOf(document.activeElement as HTMLButtonElement);
    /* Home / End pass ±Infinity: jump to the edge. Arithmetic on Infinity
       gave NaN, so Home and End used to do nothing once an item had focus. */
    const next = !Number.isFinite(delta)
      ? delta > 0
        ? list.length - 1
        : 0
      : current === -1
        ? delta > 0
          ? 0
          : list.length - 1
        : (current + delta + list.length) % list.length;
    list[next]?.focus();
  }

  function onKeyDown(e: KeyboardEvent<HTMLDivElement>) {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        focusItem(1);
        break;
      case 'ArrowUp':
        e.preventDefault();
        focusItem(-1);
        break;
      case 'Home':
        e.preventDefault();
        focusItem(Number.NEGATIVE_INFINITY);
        break;
      case 'End':
        e.preventDefault();
        focusItem(Number.POSITIVE_INFINITY);
        break;
      case 'Tab':
        onClose();
        break;
    }
  }

  let sep = 0;
  return (
    <div
      ref={panelRef}
      id={id}
      popover="auto"
      role="menu"
      aria-labelledby={labelledBy}
      className={cx('sv-menu', align === 'end' && 'sv-menu--end')}
      onKeyDown={onKeyDown}
    >
      {items.map((item) =>
        item === 'separator' ? (
          /* <hr> is already a separator to assistive tech — no role needed. */
          <hr key={`sep-${sep++}`} className="sv-menu__sep" />
        ) : (
          <button
            key={item.label}
            type="button"
            role="menuitem"
            className={cx('sv-menu__item', item.danger && 'sv-menu__item--danger')}
            disabled={item.disabled}
            onClick={() => {
              onClose();
              item.onSelect();
            }}
          >
            {item.icon && (
              <span className="sv-menu__icon" aria-hidden="true">
                {item.icon}
              </span>
            )}
            <span className="sv-menu__label">{item.label}</span>
            {item.meta && <span className="sv-menu__meta sv-mono">{item.meta}</span>}
          </button>
        ),
      )}
      {actionable.length === 0 && <p className="sv-menu__empty">{tr.noActions}</p>}
    </div>
  );
}

/* An opened menu puts focus on its first verb. B42's anchor hook only
   places the panel and returns focus on close — knowing what to focus is
   this component's business, not the primitive's. */
function focusFirstItem(open: boolean, panel: HTMLDivElement) {
  if (open) panel.querySelector<HTMLButtonElement>('[role="menuitem"]:enabled')?.focus();
}

/* ---------- MenuButton — a button whose job is opening the menu ---------- */

export interface MenuButtonProps
  extends Omit<
    ButtonHTMLAttributes<HTMLButtonElement>,
    'children' | 'popoverTarget' | 'popoverTargetAction' | 'aria-controls' | 'aria-expanded' | 'aria-haspopup'
  > {
  label: string;
  items: MenuItem[];
  variant?: ButtonVariant;
  align?: 'start' | 'end';
  disabled?: boolean;
  className?: string;
  /** Called whenever the menu opens or closes. */
  onOpenChange?: (open: boolean) => void;
}

export const MenuButton = forwardRef<HTMLButtonElement, MenuButtonProps>(function MenuButton({
  label,
  items,
  variant = 'ghost',
  align = 'start',
  disabled,
  className,
  onOpenChange,
  id: explicitId,
  ...rest
}, forwarded) {
  const id = useId();
  const menuId = `${id}-menu`;
  const btnId = explicitId ?? `${id}-btn`;
  const [open, setOpen] = useState(false);
  const { triggerRef, panelRef } = usePopoverAnchor(align, (isOpen, panel) => {
    setOpen(isOpen);
    onOpenChange?.(isOpen);
    focusFirstItem(isOpen, panel);
  });

  return (
    <>
      <Button
        {...rest}
        id={btnId}
        ref={(node) => {
          triggerRef.current = node;
          if (typeof forwarded === 'function') forwarded(node);
          else if (forwarded) forwarded.current = node;
        }}
        variant={variant}
        disabled={disabled}
        className={className}
        aria-expanded={open}
        aria-haspopup="menu"
        aria-controls={menuId}
        popoverTarget={menuId}
      >
        {label}
        <span className="sv-menubtn__chevron" aria-hidden="true" />
      </Button>
      <MenuPanel
        id={menuId}
        items={items}
        labelledBy={btnId}
        align={align}
        panelRef={panelRef}
        onClose={() => panelRef.current?.hidePopover()}
      />
    </>
  );
});

/* ---------- SplitButton — one primary action + related actions ---------- */

export interface SplitButtonProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'onClick' | 'children'> {
  /** The primary action's label — names its object ("Create order"). */
  label: string;
  onClick: () => void;
  /** The related actions behind the chevron. */
  items: MenuItem[];
  variant?: Extract<ButtonVariant, 'primary' | 'ghost'>;
  /** Accessible name for the chevron trigger. */
  menuLabel?: string;
  isLoading?: boolean;
  loadingLabel?: string;
  disabled?: boolean;
  className?: string;
}

/**
 * The split button carries ONE primary verb; the chevron opens variants
 * of the same job ("Create order" / "Create draft order"). Unrelated
 * actions belong in their own controls, not behind the chevron.
 */
export const SplitButton = forwardRef<HTMLSpanElement, SplitButtonProps>(function SplitButton({
  label,
  onClick,
  items,
  variant = 'primary',
  menuLabel: menuLabelProp,
  isLoading,
  loadingLabel,
  disabled,
  className,
  ...rest
}, ref) {
  const tr = useStrings();
  const menuLabel = menuLabelProp ?? tr.moreWaysTo(label);
  const id = useId();
  const menuId = `${id}-menu`;
  const btnId = `${id}-btn`;
  const [open, setOpen] = useState(false);
  const { triggerRef, panelRef } = usePopoverAnchor('end', (isOpen, panel) => {
    setOpen(isOpen);
    focusFirstItem(isOpen, panel);
  });

  return (
    <span {...rest} ref={ref} className={cx('sv-splitbtn', className)}>
      <Button
        id={btnId}
        variant={variant}
        onClick={onClick}
        isLoading={isLoading}
        loadingLabel={loadingLabel}
        disabled={disabled}
        className="sv-splitbtn__main"
      >
        {label}
      </Button>
      <Button
        ref={triggerRef as React.Ref<HTMLButtonElement>}
        variant={variant}
        disabled={disabled || isLoading}
        className="sv-splitbtn__toggle"
        aria-label={menuLabel}
        aria-expanded={open}
        aria-haspopup="menu"
        aria-controls={menuId}
        popoverTarget={menuId}
      >
        <span className="sv-menubtn__chevron" aria-hidden="true" />
      </Button>
      <MenuPanel
        id={menuId}
        items={items}
        labelledBy={btnId}
        align="end"
        panelRef={panelRef}
        onClose={() => panelRef.current?.hidePopover()}
      />
    </span>
  );
});

/* B20 · Menu — actions dropdown on the native popover top layer. */

@layer sv-components {
  .sv-menu {
    /* Top layer: no z-index needed. Positioned by JS from the trigger. */
    position: fixed;
    margin: 0;
    inset: auto;
    min-width: 200px;
    max-width: 300px;
    padding: var(--sv-s1);
    background: var(--sv-paper);
    border: 1px solid var(--sv-line);
    border-radius: var(--sv-r);
    box-shadow: var(--sv-shadow);
    color: var(--sv-ink);
  }

  /* ---- v0.9 · the menu arrives ----------------------------------

     B42's entrance, verbatim, because B20 is the same object doing a
     narrower job: the same top layer, the same JS placement reading
     `offsetWidth`, the same 4px offset below the trigger. Not
     posture-gated — it answers a click (dialog.css argues it in full) —
     and `--sv-t-fast` collapses under reduced motion and on paper.

     THE ITEMS DO NOT STAGGER. A menu whose rows cascade in is the one
     move on this surface that would actively cost the reader something:
     they opened it to hit a verb, and a queue of delayed children means
     the verb they were reaching for is not where it will be. The panel
     arrives; its contents are in it. */
  .sv-menu:popover-open {
    opacity: 1;
    transform: translateY(0);
    transition: opacity var(--sv-t-fast) ease-out, transform var(--sv-t-fast) ease-out;
  }

  @starting-style {
    .sv-menu:popover-open {
      opacity: 0;
      transform: translateY(-4px);
    }
  }

  .sv-menu__item {
    display: flex;
    align-items: center;
    gap: var(--sv-s2);
    width: 100%;
    padding: 7px 10px;
    border: 0;
    border-radius: var(--sv-r);
    background: none;
    font: inherit;
    font-size: 13px;
    font-weight: 500;
    color: var(--sv-ink);
    text-align: start;
    cursor: pointer;
    transition: background-color var(--sv-t-fast);
  }

  .sv-menu__item:hover:enabled,
  .sv-menu__item:focus-visible {
    background: var(--sv-seed-tint);
  }

  .sv-menu__item:focus-visible {
    outline: 2px solid var(--sv-seed-line);
    outline-offset: -2px;
  }

  .sv-menu__item:disabled {
    color: var(--sv-ink-faint);
    cursor: not-allowed;
  }

  .sv-menu__item--danger {
    color: var(--sv-bad);
  }

  .sv-menu__icon {
    display: inline-flex;
    width: 16px;
    height: 16px;
    color: var(--sv-ink-soft);
    flex: none;
  }

  .sv-menu__item--danger .sv-menu__icon {
    color: var(--sv-bad);
  }

  .sv-menu__label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .sv-menu__meta {
    font-size: 10px;
    color: var(--sv-ink-soft);
  }

  .sv-menu__sep {
    margin: var(--sv-s1) calc(-1 * var(--sv-s1));
    border: 0;
    border-top: 1px solid var(--sv-line);
  }

  .sv-menu__empty {
    padding: var(--sv-s2) 10px;
    font-size: 12.5px;
    color: var(--sv-ink-soft);
  }

  /* Chevron drawn from tokens, matching the field chevron. */
  .sv-menubtn__chevron {
    display: inline-block;
    width: 6px;
    height: 6px;
    margin-inline-start: var(--sv-s1);
    border-right: 1.5px solid currentColor; /* rule 21: chevron glyph, points down in both directions */
    border-bottom: 1.5px solid currentColor;
    transform: translateY(-2px) rotate(45deg);
  }

  /* ---- SplitButton ---- */

  .sv-splitbtn {
    display: inline-flex;
  }

  .sv-splitbtn .sv-splitbtn__main {
    border-start-end-radius: 0;
    border-end-end-radius: 0;
  }

  .sv-splitbtn .sv-splitbtn__toggle {
    border-start-start-radius: 0;
    border-end-start-radius: 0;
    padding-inline: var(--sv-s2);
  }

  .sv-splitbtn .sv-splitbtn__toggle .sv-menubtn__chevron {
    margin-inline-start: 0;
  }

  /* A hairline seam between the halves, drawn structurally. */
  .sv-splitbtn .sv-splitbtn__toggle {
    box-shadow: inset 1px 0 0 var(--sv-seed-deep);
  }

  .sv-splitbtn .sv-btn--ghost.sv-splitbtn__toggle {
    box-shadow: inset 1px 0 0 var(--sv-line);
  }

  /* RTL · the seam sits on the toggle's start edge, now its right side. */
  .sv-splitbtn .sv-splitbtn__toggle:dir(rtl) {
    box-shadow: inset -1px 0 0 var(--sv-seed-deep);
  }

  .sv-splitbtn .sv-btn--ghost.sv-splitbtn__toggle:dir(rtl) {
    box-shadow: inset -1px 0 0 var(--sv-line);
  }
}
